pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, uint8 len, uint256 seed) public {
        uint8 boundedLen = len == 0 ? 1 : len;
        vm.assume(boundedLen <= 10);

        address[] memory tos = new address[](boundedLen);
        uint[] memory vals = new uint[](boundedLen);

        for (uint8 i = 0; i < boundedLen; i++) {
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i, from)))));
            vals[i] = uint256(keccak256(abi.encodePacked(seed, i, from, uint256(i))));
        }

        bool ok;
        bool ret;
        try c.transfer(from, address(0), tos, vals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        assertTrue(!ok || ret);
    }
}
